\label{thm:calibration}
Let $X$ have full column rank and $A_0\succ0$. For $1\le s\le m$,
a calibrated $R_s\succ0$ exists if and only if
\begin{equation}\label{eq:feasibility}
 s>d_{\mathrm{eff}}(A_0):=\operatorname{tr}\{G(G+A_0)^{-1}\}.
\end{equation}
It is unique among all positive definite matrices and depends only on
$G,A_0,m,s$. At $s=m$, $R_m=A_0$. For every feasible $s<m$,
\begin{equation}\label{eq:penalty-upper}
 0\prec R_s\preceq \frac{s}{m}A_0\prec A_0.
\end{equation}
If $d\le s<m$, then
\begin{equation}\label{eq:penalty-sandwich}
 \frac{s-d+1}{m-d+1}A_0\preceq R_s\preceq\frac{s}{m}A_0.
\end{equation}
Both inequalities in \eqref{eq:penalty-sandwich} are strict when
$d>1$. If $A_0$ is scalar, $R_s$ commutes with $G$.

\label{lem:mean-identity}
For $R\succ0$,
\begin{align}
 \sum_{s=0}^m t^sZ_s(G,R)
   &=(1+t)^m\det\left(R+\frac{t}{1+t}G\right),\label{eq:partition-generating}\\
 \mathbb E_{s,R}w_S
   &=\{\nabla_G\log Z_s(G,R)\}X^\top y.\label{eq:mean-identity}
\end{align}

\label{cor:calibration-closed}
If $s=1$ is feasible, then
\begin{equation}\label{eq:singleton-penalty}
 R_1=\frac{1-d_{\mathrm{eff}}(A_0)}{m}(G+A_0).
\end{equation}
For $d=1$ and $A_0=\lambda_0>0$, every budget has
$r_s=s\lambda_0/m$.

\label{prop:loo-matrix-contact}
Under the LOO assumptions above, put $H=G+R$ and
$t_\ell=\max_i\ell_i/(1-\ell_i)$. Then
\begin{equation}\label{eq:loo-matrix-ceiling}
 \Sigma_{m-1}(y)\preceq J_0(y)\frac{t_\ell}{D}H^{-1}.
\end{equation}
For $y\ne0$, the kernel of the difference in \eqref{eq:loo-matrix-ceiling}
is nonzero exactly when $X^\top y=0$ and all rows in
$\operatorname{supp}(y)$ are signed copies of one nonzero vector $v$
with globally maximal calibrated leverage $v^\top H^{-1}v$.
In that case the complete kernel in the original coefficient query
coordinates is $\operatorname{span}(v)$; otherwise it is zero.

\label{thm:sharp-geometry}
For the balanced design above, every $d\le s<nd$ satisfies
$\alpha_s>\beta_s$ and $\tau_s>0$. For any fixed nonzero $W\succeq0$,
put $c=\max_jW_{jj}$ and $I_{\max}=\{j:W_{jj}=c\}$. Then
\begin{equation}\label{eq:sharp-balanced}
 h_s(X,W)=\alpha_s c.
\end{equation}
The nonzero maximizing responses are exactly the nonzero elements of
\begin{equation}\label{eq:old-space}
 \mathcal E=\{y:q=0,\ z_i=0\text{ for }i\text{ in groups outside }I_{\max}\}.
\end{equation}
This raw response space has dimension $(n-1)|I_{\max}|$ and is the same
for every stated budget at the fixed target and query.

\label{thm:etf-query}
Under these assumptions, fix any nonzero $W\succeq0$ and put
$w=\operatorname{tr}(W)/d$. The following are equivalent:
\begin{enumerate}
\item $x_i^\top Wx_i=w$ for every original row;
\item every nonzero response in $\ker(X^\top)$ globally maximizes risk;
\item the complete maximizing space is $\ker(X^\top)$.
\end{enumerate}
When they hold, $h_{m-2}(X,W)=wc_R$, and the maximizing space has
dimension $m-d$. Singular queries are included.

\label{app:etf-proof}
\par\medskip\noindent\textbf{Calibration and the centered operator.}
Assume the ETF conditions of Theorem~\ref{thm:etf-query}. Put
$T=XX^\top$, $P=T/g$, $P_\perp=I-P$, $q=\mu^2=(g-1)/(m-1)$,
and $h=g-1$. Here $q$ is the squared ETF coherence, not a group mean.
Let $k=m-d\ge2$. Then
\begin{equation}\label{eq:etf-retained-positive}
 h^2-q=\frac{k\{k(m-1)-d\}}{d^2(m-1)}>0,
 \qquad k(m-1)-d=(k-1)m>0.
\end{equation}
The Gram matrix after deleting two rows has eigenvalues $g$ with
multiplicity $d-2$, and $h+\mu,h-\mu$. All are positive.

For a positive raw penalty $r$, define
\begin{equation}\label{eq:etf-basic-coefficients}
 b=(g+r)^{-1},\quad a=1-b,\quad \ell=1-bg=br,\quad
 \delta=a^2-b^2q,\quad N=\binom m2,\quad
 L=I-bT=P_\perp+\ell P.
\end{equation}
For a deleted pair $D_0=\{i,j\}$ let $E_{D_0}$ select its two
coordinates, $X_{D_0}=E_{D_0}X$, and $t=T_{ij}$. Its deletion matrix is
\begin{equation}\label{eq:etf-pair-inverse}
 Q_{D_0}=I_2-bE_{D_0}TE_{D_0}^\top
 =\begin{pmatrix}a&-bt\\-bt&a\end{pmatrix},\qquad
 Q_{D_0}^{-1}=\delta^{-1}\begin{pmatrix}a&bt\\bt&a\end{pmatrix}.
\end{equation}
The deletion matrix $Q_{D_0}$ is positive definite. Every retained determinant is
$(g+r)^d\delta$, so the actual law is uniform on the $N$ original
pairs. This is the pair geometry associated with ETFs
\citep{bodmann2005}; it does not use a rotation of the response coordinates.
The fit can be written as
\begin{equation}\label{eq:etf-correction}
 w_S=bX^\top y-z_{D_0}(y),\qquad
 z_{D_0}(y)=bX_{D_0}^\top Q_{D_0}^{-1}E_{D_0}Ly.
\end{equation}
Counting diagonal and off-diagonal pair occurrences gives
\begin{align}
 \sum_{D_0}E_{D_0}^\top Q_{D_0}^{-1}E_{D_0}
  &=\delta^{-1}\{[(m-1)a-b]I+bT\},\nonumber\\
 e&=(m-1)a+b(g-1),\qquad
 \eta=\frac{b\ell e}{N\delta}>0,\nonumber\\
 \mathbb E z_{D_0}(y)&=\eta X^\top y,\qquad
 \mathbb E w_S=f(r)X^\top y,\quad f(r)=b-\eta.\label{eq:etf-mean}
\end{align}
To identify $f$, apply this mean identity to $y=Xv$ and take traces
of the mean fit map. The retained spectrum above gives
\begin{equation}\label{eq:etf-calibration}
 f(r)=\frac1m\left\{
 \frac{(d-2)g}{g+r}+
 \frac{h+\mu}{h+\mu+r}+\frac{h-\mu}{h-\mu+r}\right\}.
\end{equation}
It decreases continuously and strictly from $1/g$ to zero. Hence every
prescribed $\lambda_0>0$ has exactly one positive scalar solution of
$f(r)=1/(g+\lambda_0)$. Theorem~\ref{thm:calibration} gives uniqueness
among all SPD penalties because $s=m-2\ge d$ is feasible. At this
calibration,
\begin{equation}\label{eq:etf-full-loss}
 k_F=1-gf=\frac{\lambda_0}{g+\lambda_0}=\ell+g\eta>0,
 \qquad K=P_\perp+k_FP.
\end{equation}
Thus this construction reaches a prescribed target, not just a target
chosen after the raw penalty.

\par\medskip\noindent\textbf{The operator for any symmetric query.}
Let $H=XWX^\top$, $h_i=H_{ii}$, and $D_h=\operatorname{diag}(h_i)$.
Define
\begin{equation}\label{eq:etf-operator-coefficients}
 \alpha=a^2(m-2)+2ab(g-2)-2b^2q,\quad
 \beta=b^2q,\quad \gamma=ab,\quad \theta=a^2+b^2q.
\end{equation}
The coefficient covariance is
\begin{equation}\label{eq:etf-actual-covariance}
 \operatorname{Cov}(w_S(y))=
 \frac1N\sum_{D_0}z_{D_0}(y)z_{D_0}(y)^\top
   -\eta^2X^\top yy^\top X.
\end{equation}
For a pair $D_0=\{i,j\}$, signed multiplication in
\eqref{eq:etf-pair-inverse} gives
\begin{align}
 (Q_{D_0}^{-1}H_{D_0D_0}Q_{D_0}^{-1})_{11}
  &=\frac{a^2h_i+2ab\,tH_{ij}+b^2q h_j}{\delta^2},\nonumber\\
 (Q_{D_0}^{-1}H_{D_0D_0}Q_{D_0}^{-1})_{12}
  &=\frac{ab\,t(h_i+h_j)+\theta H_{ij}}{\delta^2}.
 \label{eq:etf-signed-product}
\end{align}
The second diagonal entry swaps $i,j$. Since $TH=HT=gH$, summing the
first line over $j\ne i$ has numerator
$[a^2(m-1)+2ab(g-1)-b^2q]h_i+b^2q\operatorname{tr}(H)$.
Each off-diagonal entry occurs in one pair. Therefore
\begin{align}
 M_W&=\frac{\alpha D_h+\beta\operatorname{tr}(H)I
                 +\gamma(TD_h+D_hT)+\theta H}{N\delta^2},\nonumber\\
 C&=b^2LM_WL-\eta^2H.\label{eq:etf-arbitrary-operator}
\end{align}
This is the response operator, not the coefficient covariance matrix.
The last subtraction centers at the actual mean in \eqref{eq:etf-mean}.
Before imposing any flatness, its cross block is
\begin{equation}\label{eq:etf-cross-block}
 P_\perp CP=\frac{b^2\ell(\alpha+g\gamma)}{N\delta^2}P_\perp D_hP.
\end{equation}
Indeed $H$ and $T$ kill residuals, while $L$ acts as the identity on
residuals and as $\ell$ on the fitted space.

\par\medskip\noindent\textbf{Flat-query deficit, strict signs, and converse.}
If $h_i=w=\operatorname{tr}(W)/d$ for every row, then
$D_h=wI$ and $\operatorname{tr}(H)=mw$. Define
\begin{align}
 A&=\alpha+m\beta=(m-2)(a^2+b^2q)+2ab(g-2),\nonumber\\
 c_R&=\frac{b^2A}{N\delta^2},\qquad
 u=\frac{b^2\ell^2(A+2gab)}{N\delta^2},\nonumber\\
 \tau&=\frac{b^2\ell^2(e^2-N\theta)}{N^2\delta^2},\qquad
 \xi=c_Rk_F-u.\label{eq:etf-flat-coefficients}
\end{align}
Substitute $D_h=wI$ in \eqref{eq:etf-arbitrary-operator} and use
$LH=HL=\ell H$. The result is
\begin{equation}\label{eq:etf-flat-deficit}
 C=wc_RP_\perp+wuP-\tau H,\qquad
 wc_RK-C=w\xi P+\tau H.
\end{equation}
The coefficient $c_R$ is \eqref{eq:etf-cr}. It is also the isotropic
residual coefficient: its numerator is
$(m-1)[a^2+b(2a+b)q]-[a^2+2ab+b^2q]=A$,
using $(m-1)q=g-1$.

We now prove all strict signs needed for sufficiency and necessity.
The assumptions imply
\begin{equation}\label{eq:etf-sign-domain}
 m\ge4,\qquad h=g-1\ge\frac2{m-2}>0,\qquad
 mh>2,\qquad a=b(h+r)>bh,\qquad 0<\ell<1.
\end{equation}
First,
\begin{equation}
 A-2a\ell=a[(m-4)a+2b(2g-3)]+(m-2)b^2q>0.
\end{equation}
To check the sign even if $2g-3<0$, the expression in square brackets
is at least $b[(m-4)h+2(2g-3)]=b(mh-2)>0$.
Since $k_F=\ell+g\eta>\ell$, it follows that
\begin{equation}\label{eq:etf-xi-positive}
 \xi=\frac{b^2\{A(k_F-\ell^2)-2gab\ell^2\}}{N\delta^2}
 >\frac{b^3g\ell(A-2a\ell)}{N\delta^2}>0.
\end{equation}
In particular $A>0$, so $c_R>0$.

For the second sign put $t_0=a/b=h+r>h$. Then
\begin{equation}
 \frac{e^2-N\theta}{b^2}=F(t_0),\qquad
 F(t)=\frac{(m-1)(m-2)}2t^2+2(m-1)th+h^2-\frac{mh}2.
\end{equation}
This polynomial increases strictly for $t\ge h>0$, and
$F(h)=mh[(m+1)h-1]/2>0$. Hence $\tau>0$.
Finally,
\begin{equation}
 \frac{\alpha+g\gamma}{b^2}=G(t_0),\qquad
 G(t)=(m-2)t^2+(3h-1)t-\frac{2h}{m-1}.
\end{equation}
For $t\ge h$,
$G'(t)\ge2(m-2)h+3h-1\ge3+3h>0$.
Also $G(h)=h[(m+1)h-1-2/(m-1)]>0$, because
$(m+1)h\ge2(m+1)/(m-2)>2$ and $1+2/(m-1)\le5/3$.
Thus $\alpha+g\gamma>0$ and the scalar in
\eqref{eq:etf-cross-block} is strictly positive. These signs hold for
all positive raw penalties in the stated domain.

For $W\succeq0$, $W\ne0$, we have $H\succeq0$ and $w>0$.
The first term in \eqref{eq:etf-flat-deficit} has kernel
$\ker(X^\top)$ and the second term vanishes on that space. Consequently
\begin{equation}
 \ker(wc_RK-C)=\ker(X^\top).
\end{equation}
There are $m-d>0$ residual dimensions. They attain $wc_R$, while every
response with a fitted component has strictly smaller normalized risk.
The argument does not invert $W$, so singular queries are included.
For $W=wI$, writing $c_F=u-g\tau$ gives the isotropic sector gap
$c_Rk_F-c_F=\xi+g\tau>0$. Positivity of covariance also gives $c_F\ge0$.
Thus no separate sign certificate for that special case is needed here.

For necessity, suppose every nonzero residual is a global maximizer,
with sharp value $h_\star$. Since $K\succ0$, full Rayleigh stationarity
gives $Cz=h_\star Kz=h_\star z$ on residuals. Hence $PCP_\perp=0$,
and by symmetry $P_\perp CP=0$. The positive coefficient in
\eqref{eq:etf-cross-block} implies $P_\perp D_hP=PD_hP_\perp=0$.
Thus $D_h$ commutes with $P$. Entrywise,
$(h_i-h_j)T_{ij}/g=0$. Every off-diagonal $T_{ij}$ is nonzero since
$q>0$, so all $h_i$ agree. Their sum is $g\operatorname{tr}(W)=mw$;
therefore each is $w$. This proves the equivalence in
Theorem~\ref{thm:etf-query}. Constancy of a residual compression alone
would not prove this converse; the cross block is essential.

\label{prop:mixture}
Under the assumptions of Theorem~\ref{thm:sharp-geometry}, an explicit
$T_s>0$, depending only on the features, target, and budget, satisfies
the following. For every $0<t\le T_s$ and every nonzero $W\succeq0$,
\begin{align*}
 \sup_{y\ne0}\frac{\operatorname{tr}(W\operatorname{Cov}(w(t)))}{J_0(y)}
 &=\alpha_s(t)\max_jW_{jj}\\
 &<\alpha_s(0)\max_jW_{jj}.
\end{align*}
The complete maximizing raw response space remains $\mathcal E$.

\label{thm:gain}
Fix a balanced base, target and budget from Proposition~\ref{prop:mixture}.
Write $\alpha(t)=A-Dt+Qt^2$ and $T=T_s$.
There are explicit $r_1,C>0$, independent of query and weight, such that
for $\epsilon=\|H/\sqrt{\lambda_0}\|_F\le r_1$, every nonzero PSD $W$
and every $0<t\le T$ satisfy, with $c=\max_jW_{jj}$,
\begin{equation}\label{eq:gain-modulus}
 |h_R(X,W)-h_t(X,W)-t(D-Qt)c|\le Ct\epsilon c.
\end{equation}
Thus $\epsilon\le\min\{r_1,D/(4C)\}$ gives gain at least $Dtc/4>0$.
